#include "alu_6502.h"

/* ========== FROZEN SHAPES ========== */
static inline uint8_t shape_add(uint8_t a, uint8_t b) {
    return (uint8_t)((a + b) & 0xFF);
}

static inline uint8_t shape_sub(uint8_t a, uint8_t b) {
    return (uint8_t)((a - b) & 0xFF);
}

static inline uint8_t shape_and(uint8_t a, uint8_t b) {
    return (uint8_t)(a & b);
}

static inline uint8_t shape_or(uint8_t a, uint8_t b) {
    return (uint8_t)(a | b);
}

static inline uint8_t shape_xor(uint8_t a, uint8_t b) {
    return (uint8_t)(a ^ b);
}

static inline uint8_t shape_identity(uint8_t a, uint8_t b) {
    (void)b;  /* unused for unary op */
    return (uint8_t)(a);
}


